package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"

	"github.com/gorilla/websocket"
)

type User struct {
	ID       string `json:"id"`
	Username string `json:"username"`
	Role     string `json:"role"`
}

type Message struct {
	Action  string          `json:"action"`
	Payload json.RawMessage `json:"payload"`
}

type RoleUpdate struct {
	TargetUser string `json:"target_user"`
	NewRole    string `json:"new_role"`
}

var (
	upgrader = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
	users     = make(map[string]*User)
	usersLock sync.RWMutex
)

func init() {
	users["user1"] = &User{ID: "user1", Username: "alice", Role: "viewer"}
	users["user2"] = &User{ID: "user2", Username: "bob", Role: "editor"}
	users["admin1"] = &User{ID: "admin1", Username: "charlie", Role: "admin"}
}

func authenticateFromHeader(r *http.Request) *User {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		return nil
	}
	usersLock.RLock()
	defer usersLock.RUnlock()
	return users[userID]
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	user := authenticateFromHeader(r)
	if user == nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	log.Printf("User %s connected with role %s", user.Username, user.Role)

	for {
		_, msgBytes, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg Message
		if err := json.Unmarshal(msgBytes, &msg); err != nil {
			conn.WriteJSON(map[string]string{"error": "invalid message format"})
			continue
		}

		switch msg.Action {
		case "get_users":
			handleGetUsers(conn, user)
		case "update_role":
			handleUpdateRole(conn, user, msg.Payload)
		case "send_notification":
			handleSendNotification(conn, user, msg.Payload)
		default:
			conn.WriteJSON(map[string]string{"error": "unknown action"})
		}
	}
}

func handleGetUsers(conn *websocket.Conn, requester *User) {
	usersLock.RLock()
	defer usersLock.RUnlock()
	conn.WriteJSON(users)
}

func handleUpdateRole(conn *websocket.Conn, requester *User, payload json.RawMessage) {
	var update RoleUpdate
	if err := json.Unmarshal(payload, &update); err != nil {
		conn.WriteJSON(map[string]string{"error": "invalid payload"})
		return
	}

	// VULNERABILITY: Role check uses the user's current role from the shared map,
	// but the role could have been updated by the user themselves in a prior message
	// within the same connection. The check below re-reads from the map.
	usersLock.RLock()
	currentRequester := users[requester.ID]
	usersLock.RUnlock()

	if currentRequester == nil || !strings.EqualFold(currentRequester.Role, "admin") {
		conn.WriteJSON(map[string]string{"error": "insufficient permissions"})
		return
	}

	validRoles := []string{"viewer", "editor", "admin"}
	roleValid := false
	for _, r := range validRoles {
		if strings.EqualFold(update.NewRole, r) {
			roleValid = true
			break
		}
	}
	if !roleValid {
		conn.WriteJSON(map[string]string{"error": "invalid role"})
		return
	}

	usersLock.Lock()
	if target, ok := users[update.TargetUser]; ok {
		target.Role = update.NewRole
		log.Printf("Role updated: %s -> %s by %s", target.Username, update.NewRole, requester.Username)
		conn.WriteJSON(map[string]string{"status": "role updated"})
	} else {
		conn.WriteJSON(map[string]string{"error": "user not found"})
	}
	usersLock.Unlock()
}

func handleSendNotification(conn *websocket.Conn, requester *User, payload json.RawMessage) {
	var notif map[string]string
	if err := json.Unmarshal(payload, &notif); err != nil {
		conn.WriteJSON(map[string]string{"error": "invalid payload"})
		return
	}
	conn.WriteJSON(map[string]string{"status": fmt.Sprintf("notification sent: %s", notif["message"])})
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":0.0.0.0:8080", nil))
}
